func(m regexpMatcher)Match(s string)bool{return m.re.MatchString(s)}
type prefixSuffixMatcher struct{prefix,suffix string;m Matcher}
func(m prefixSuffixMatcher)Match(s string)bool{if "'!strings.HasPrefix(s,m.prefix)||!strings.HasSuffix(s,m.suffix){return false};return m.m.Match(strings.TrimSuffix(strings.TrimPrefix(s,m.prefix),m.suffix))}
type notMatcher struct{m Matcher}
func(m notMatcher)Match(s string)bool{return !m.m.Match(s)}
EOF
gofmt -w lib/utils/parse/parse.go
go test ./lib/utils/parse'
